// =========================================================================
// Node I/O Example Tests
// =========================================================================

// These tests verify individual node behavior against specified examples.
// Each test executes a single node with given inputs and checks outputs.

/// Node example: std.credentials::env_credential (example 0)
/// 
/// Tests that node 'std.credentials::env_credential' produces expected outputs for given inputs.
#[test]
fn test_example_std_credentials_env_credential_0() {
    if !guard_test("test_example_std_credentials_env_credential_0", TestClass::Unit, FermiCost::XS, &[], &[]) {
    return;
};
    let dag = gunbc_resolve::builder::build_dsl_graph_dag("std/credentials.dag", gunbc_resolve::BuildOpts::default()).expect("graph should build");
    let mut inputs = std::collections::HashMap::new();
    inputs.insert("__deps".to_string(), Value::List(vec![Value::Str("mock".to_string())]));
    inputs.insert("__out:token".to_string(), Value::Secret(gunbc_ir::SecretString::new("***")));
    inputs.insert("env_var".to_string(), Value::Str("example".to_string()));
    inputs.insert("token".to_string(), Value::Secret(gunbc_ir::SecretString::new("***")));
    let outputs = gunbc_exec::execute_single_node(&dag, "std.credentials::env_credential", inputs, gunbc_exec::ExecutionMode::Real).expect("node 'std.credentials::env_credential' should execute successfully");

    // Check output port 'token'
    let output_token = outputs.get("token").expect("output port 'token' should exist");
    assert!(matches!(*output_token, Value::Secret(_)) || matches!(*output_token, Value::Skipped), "expected Secret or Skipped for output_token");
}

